vedVote = getCookie(cookieKey); if (savedVote == 'dislike') { event_label = "Thumbs Up|Three dead, curfews in four districts: Why Nepal is battling its worst communal unrest in recent years|iOS"; aiSummaryAppGAEvent(event_label); } } handleVote("like"); } function dislikeBtnEvent (currentObj) { if (typeof window.aiSummeryClickEvent === "function") { const articleId = voteBox.dataset.articleId; const cookieKey = "vote_" + articleId; const savedVote = getCookie(cookieKey); if (savedVote == 'like') { event_label = "Thumbs Down|Three dead, curfews in four districts: Why Nepal is battling its worst communal unrest in recent years|Desktop"; aiSummeryClickEvent(event_label); } } if (typeof window.aiSummaryAppGAEvent === "function") { const articleId = voteBox.dataset.articleId; const cookieKey = "vote_" + articleId; const savedVote = getCookie(cookieKey); if (savedVote == 'like') { event_label = "Thumbs Down|Three dead, curfews in four districts: Why Nepal is battling its worst communal unrest in recent years|iOS"; aiSummaryAppGAEvent(event_label); } } handleVote("dislike"); }

